/**
 * status-coverage — the pure core behind `require-status-matches-coverage`.
 *
 * The coverage math itself (`statementCoverage` -> `coverageTier` ->
 * `expectedStatus`) lives in `@re-cinq/lore-shared` because spec-status-upkeep
 * FR1 opens the PR that fixes what this rule reports, and the two must agree on
 * what a doc's links entitle it to claim. What is rule-specific — comparing that
 * against the declared status, and locating the row a human has to edit — lives
 * here.
 *
 * Split out of the rule so it is testable without a RuleTester.
 */
import { coverageTier, expectedStatus, parseDocStatus, statementCoverage, statusTier, } from "./spec-parsers.mjs";
/**
 * @typedef {{ reason: "untagged", line: number }} UntaggedMismatch
 * @typedef {{ reason: "tier", expected: string, actual: string, testable: number, linked: number, line: number }} TierMismatch
 */
/**
 * 1-based line of the doc's declared status, so a report anchors on the cell a
 * human has to edit. Mirrors the source shapes `parseDocStatus` reads — a spec's
 * `| Status | <value> |` table row, an ADR's frontmatter `status:` — including
 * its first-match-wins rule (several API-route specs carry a second
 * `| Status | Body |` table documenting HTTP codes; the header row wins).
 *
 * @returns {number | null} null when the doc declares no status at all
 */
function statusLine(content, kind) {
    const lines = content.split(/\r?\n/);
    if (kind === "spec") {
        const index = lines.findIndex((line) => {
            const cells = line.split("|").map((cell) => cell.trim());
            return cells.length >= 3 && cells[1].toLowerCase() === "status";
        });
        return index === -1 ? null : index + 1;
    }
    if (!/^---\r?\n([\s\S]*?)\r?\n---/.test(content)) {
        return null;
    }
    const index = lines.findIndex((line) => /^status\s*:\s*(.+?)\s*$/i.test(line));
    return index === -1 ? null : index + 1;
}
/**
 * @param {string} content markdown body of a spec.md / ADR file
 * @param {"spec" | "adr"} kind
 * @returns {UntaggedMismatch | TierMismatch | null} null when the doc is consistent or skipped
 */
export function statusMismatch(content, kind) {
    const { status } = parseDocStatus(content, kind);
    if (statusTier(status) === "skip") {
        return null;
    }
    const line = statusLine(content, kind) ?? 1;
    if (status === null) {
        return { reason: "untagged", line };
    }
    const { testable, linked } = statementCoverage(content);
    const expected = expectedStatus(coverageTier(testable, linked));
    if (expected === null || expected === status) {
        return null;
    }
    return { reason: "tier", expected, actual: status, testable, linked, line };
}

/**
 * max-expects — one assertion per test. A test that checks five fields with
 * five `expect` calls stops at the first failure and hides the other four;
 * `expect(result).toEqual({...})` shows the whole diff at once, and a test
 * that genuinely needs two unrelated assertions is two tests.
 *
 * What counts: inside the callback of `it(...)` / `test(...)` and their
 * `.only` / `.skip` / `.each(...)` forms, every `expect(...)` call — the
 * ROOT call, so `expect(x).resolves.toEqual(y)` is one, not three.
 * `expect.assertions(n)` and `expect.hasAssertions()` are bookkeeping, not
 * assertions, and are not counted. Helper functions declared inside the test
 * body count toward the test that contains them: hiding assertions in a local
 * closure does not make the test smaller.
 *
 * Reported at the test call. Detect-only: which assertions merge into one
 * object and which become their own test is the author's call.
 */
const TEST_ROOTS = new Set(["it", "test"]);
const TEST_MODIFIERS = new Set(["only", "skip", "each", "concurrent"]);
function isTestRoot(node) {
    return node.type === "Identifier" && TEST_ROOTS.has(node.name);
}
function isTestModifier(node) {
    return (node.type === "MemberExpression" &&
        !node.computed &&
        isTestRoot(node.object) &&
        TEST_MODIFIERS.has(node.property.name));
}
function isTestCall(node) {
    const { callee } = node;
    if (isTestRoot(callee) || isTestModifier(callee)) {
        return true;
    }
    // it.each(table)("name", fn) — the callee is itself the `it.each(...)` call
    return callee.type === "CallExpression" && isTestModifier(callee.callee);
}
function isExpectRootCall(node) {
    return node.callee.type === "Identifier" && node.callee.name === "expect";
}
export default {
    meta: {
        type: "suggestion",
        docs: {
            description: "Enforce a maximum number of expect calls per it/test callback (default 1)",
        },
        schema: [
            {
                type: "object",
                properties: {
                    max: { type: "integer", minimum: 1 },
                },
                additionalProperties: false,
            },
        ],
        messages: {
            tooManyExpects: "Test has {{count}} expect calls (max {{max}}); assert one object with toEqual/toMatchObject or split the test",
        },
    },
    create(context) {
        const max = context.options[0]?.max ?? 1;
        const openTests = [];
        return {
            CallExpression(node) {
                if (isTestCall(node)) {
                    openTests.push({ node, count: 0 });
                    return;
                }
                if (isExpectRootCall(node) && openTests.length > 0) {
                    openTests[openTests.length - 1].count += 1;
                }
            },
            "CallExpression:exit"(node) {
                if (!isTestCall(node)) {
                    return;
                }
                const { count } = openTests.pop();
                if (count > max) {
                    context.report({
                        node,
                        messageId: "tooManyExpects",
                        data: { count, max },
                    });
                }
            },
        };
    },
};

