import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('passes valid input with enum and extra properties through unchanged once', async () => {
    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'weather_check',
        description: 'Check weather',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
            units: {type: 'string', enum: ['celsius', 'fahrenheit']},
          },
          required: ['location'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return 'ok';
      }
    );

    const response = await registry.execute('weather_check', {
      location: 'Berlin',
      units: 'celsius',
      extraFlag: true,
    });

    expect({receivedInputs, result: response.result}).toEqual({
      receivedInputs: [{location: 'Berlin', units: 'celsius', extraFlag: true}],
      result: 'ok',
    });
  });

  it('rejects an invalid enum value without invoking the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'unit_lookup',
        description: 'Look up units',
        inputSchema: {
          type: 'object',
          properties: {
            units: {type: 'string', enum: ['celsius', 'fahrenheit']},
          },
          required: ['units'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('unit_lookup', {units: 'kelvin'});

    expect({
      executorCalls,
      mentionsField: response.result.includes('units'),
      leaksValue: response.result.includes('kelvin'),
    }).toEqual({
      executorCalls: 0,
      mentionsField: true,
      leaksValue: false,
    });
  });

  it('throws Unknown tool when execute is called for an unregistered name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });

  it('compiles a static tool inputSchema once across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    let executorCalls = 0;
    const baseSchema: Record<string, unknown> = {
      type: 'object',
      properties: {query: {type: 'string'}},
      required: ['query'],
    };

    registry.register(
      {
        name: 'static_search',
        description: 'Static search tool',
        get inputSchema(): Record<string, unknown> {
          schemaReads += 1;
          return baseSchema;
        },
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    for (let index = 0; index < 10; index += 1) {
      await registry.execute('static_search', {query: 'hello'});
    }

    expect({schemaReads, executorCalls}).toEqual({schemaReads: 1, executorCalls: 10});
  });

  it('validates function-valued tool definitions against each returned schema and caches by schema reference', async () => {
    const registry = new ToolRegistry();
    const citySchema: Record<string, unknown> = {
      type: 'object',
      properties: {city: {type: 'string'}},
      required: ['city'],
    };
    const countrySchema: Record<string, unknown> = {
      type: 'object',
      properties: {country: {type: 'string'}},
      required: ['country'],
    };
    const schemas = [citySchema, citySchema, citySchema, countrySchema];
    let schemaIndex = 0;
    let executorCalls = 0;

    registry.register(
      () => {
        const currentSchema = schemas[schemaIndex] ?? countrySchema;
        schemaIndex += 1;
        return {
          name: 'dynamic_geo',
          description: 'Dynamic geo tool',
          inputSchema: currentSchema,
        };
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const first = await registry.execute('dynamic_geo', {city: 'Paris'});
    const second = await registry.execute('dynamic_geo', {country: 'France'});
    const third = await registry.execute('dynamic_geo', {country: 'France'});

    expect({
      firstResult: first.result,
      secondMentionsCity: second.result.includes('city'),
      thirdResult: third.result,
      executorCalls,
    }).toEqual({
      firstResult: 'ok',
      secondMentionsCity: true,
      thirdResult: 'ok',
      executorCalls: 2,
    });
  });
});

